  /**
   * Cursor iteration (bidirectional stream)
   */
  openCursor(
    requests: AsyncIterable<Init<CursorClientMessage>>,
  ): AsyncIterable<CursorResponse> {
    return mapRecv(
      this.client.openCursor(mapSend(requests, toWireCursorClientMessage)),
      fromWireCursorResponse,
    );
  }

  /**
   * Transaction stream. The first client message must be
   * BeginTransactionRequest. Stream close before commit aborts the transaction.
   */
  transaction(
    requests: AsyncIterable<Init<TransactionClientMessage>>,
  ): AsyncIterable<TransactionServerMessage> {
    return mapRecv(
      this.client.transaction(
        mapSend(requests, toWireTransactionClientMessage),
      ),
      fromWireTransactionServerMessage,
    );
  }
